def build_prompt(task: Dict[str, str], seed: int, item_id: str) > str:
    kind = task["kind"]
    domain = task["domain"]
    difficulty = task["difficulty"]
    return (
        "Kizárólag magyar nyelven dolgozz.\n"
        "Kizárólag eredeti, saját szöveget írj; semmit ne idézz szó szerint külső forrásból.\n"
        "Ne írj személyes adatot (valós név+cím+telefonszám, email, azonosító, jelszó, bankkártya), és ne modellezz valós személyeket.\n"
        "Ne találj ki tényeket. Ha valami nem biztos, inkább hagyd ki, vagy fogalmazz óvatosan és ellenőrizhetően.\n"
        "A kimenetnek a megadott JSON sémát kell követnie, és csak egyetlen JSON objektumot adj vissza, körítés nélkül.\n"
        f"Az 'id' mező értéke pontosan ez legyen: {item_id}\n"
        f"A 'kind' mező értéke pontosan ez legyen: {kind}\n"
        f"A 'domain' mező értéke pontosan ez legyen: {domain}\n"
        f"A 'difficulty' mező értéke pontosan ez legyen: {difficulty}\n"
        "A 'language' mező értéke pontosan: hu\n"
        "A 'safety' mezőben: pii=false, copyright_safe=true, hallucination_risk=low vagy medium, notes pedig rövid, lényegi mondat.\n"
        "A 'sources' mezőbe csak valós, ellenőrizhető URLek kerüljenek, kizárólag akkor, ha tényszerű részhez ténylegesen használtad a webeszközt.\n"
        "A 'content' legalább 800 karakter, magyar, nyelvhelyes, természetes, változatos.\n"
        f"Seed: {seed}\n"
        "Most add vissza a JSONt a séma szerint.\n"
    )

def build_repair_prompt(task: Dict[str, str], item_id: str, bad_text: str) > str:
    kind = task["kind"]
    domain = task["domain"]
    difficulty = task["difficulty"]
    return (
        "Javítsd az alábbi kimenetet úgy, hogy kizárólag egyetlen, érvényes JSON objektum legyen, és pontosan megfeleljen a megadott sémának.\n"
        "Semmilyen magyarázatot ne adj, csak a JSONt.\n"
        f"Elvárt mezők: id={item_id}, kind={kind}, language=hu, domain={domain}, difficulty={difficulty}, sources(list), content(string >=800), safety(obj: pii=false, copyright_safe=true, hallucination_risk=low/medium, notes=string).\n"
        "Kizárólag eredeti, saját szöveget írj; ne idézz külső forrásból.\n"
        "Ne írj személyes adatot.\n"
        "Hibás bemenet:\n"
        + bad_text
    )

def normalize_obj(obj: Dict[str, Any], task: Dict[str, str], item_id: str, citations: Optional[List[str]] = None) > Dict[str, Any]:
    out: Dict[str, Any] = {}
    out["id"] = obj.get("id") if isinstance(obj.get("id"), str) and len(obj.get("id", "")) >= 8 else item_id
    out["kind"] = task["kind"]
    out["language"] = "hu"
    out["domain"] = task["domain"]
    out["difficulty"] = task["difficulty"]
    sources: List[str] = []
    raw_sources = obj.get("sources")
    if isinstance(raw_sources, list):
        for u in raw_sources:
            if isinstance(u, str) and u.startswith("http"):
                sources.append(u)
    if citations:
        for u in citations:
            if isinstance(u, str) and u.startswith("http"):
                sources.append(u)
    out["sources"] = list(dict.fromkeys(sources))
    content = obj.get("content")
    out["content"] = content if isinstance(content, str) else ""
    safety_in = obj.get("safety")
    safety: Dict[str, Any] = {}
    if isinstance(safety_in, dict):
        safety["pii"] = False if safety_in.get("pii") is False else False
        safety["copyright_safe"] = True if safety_in.get("copyright_safe") is True else True
        hr = safety_in.get("hallucination_risk")
        safety["hallucination_risk"] = hr if hr in ("low", "medium") else "medium"
        notes = safety_in.get("notes")
        safety["notes"] = notes if isinstance(notes, str) and notes.strip() else "Automatikusan normalizált biztonsági mezők."
    else:
        safety = {"pii": False, "copyright_safe": True, "hallucination_risk": "medium", "notes": "Hiányzó safety mezők automatikusan pótolva."}
    out["safety"] = safety
    return out

class RotatingJsonlWriter:
    def __init__(self, out_dir: str, prefix: str, bytes_per_file: int) > None:
        self.out_dir = out_dir
        self.prefix = prefix
        self.bytes_per_file = bytes_per_file
        self.state_path = os.path.join(out_dir, f"{prefix}.state.json")
        self.file_index = 1
        self.bytes_written_current = 0
        self.fh = None
        safe_mkdir(out_dir)
        self._load_state()
        self._open_current()

    def _load_state(self) > None:
        try:
            with open(self.state_path, "rb") as f:
                st = json.loads(f.read().decode("utf8"))
            if isinstance(st, dict):
                self.file_index = int(st.get("file_index", 1))
        except Exception:
            self.file_index = 1

    def _save_state(self) > None:
        st = {"file_index": self.file_index, "updated_at": now_utc_iso()}
        tmp = self.state_path + ".tmp"
        with open(tmp, "wb") as f:
            f.write(json.dumps(st, ensure_ascii=False).encode("utf8"))
        os.replace(tmp, self.state_path)

    def _file_path(self, idx: int) > str:
        return os.path.join(self.out_dir, f"{self.prefix}_{idx:06d}.jsonl")

    def _open_current(self) > None:
        if self.fh is not None:
            try:
                self.fh.close()
            except Exception:
                pass
        path = self._file_path(self.file_index)
        self.fh = open(path, "ab")
        try:
            self.fh.seek(0, 2)
            self.bytes_written_current = int(self.fh.tell())
        except Exception:
            self.bytes_written_current = 0

    def _rotate(self) > None:
        if self.fh is not None:
            try:
                self.fh.flush()
            except Exception:
                pass
        self.file_index += 1
        self._save_state()
        self._open_current()

    def write_obj(self, obj: Dict[str, Any]) > Tuple[str, int, int]:
        line = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf8")
        if self.bytes_written_current + len(line) > self.bytes_per_file:
            self._rotate()
        if self.fh is None:
            raise RuntimeError("Writer nincs megnyitva")
        self.fh.write(line)
        self.fh.flush()
        self.bytes_written_current += len(line)
        return self._file_path(self.file_index), self.file_index, self.bytes_written_current

class JsonlAppendWriter:
    def __init__(self, path: str) > None:
        self.path = path
        safe_mkdir(os.path.dirname(path) or ".")
        self.fh = open(path, "ab")

    def write(self, obj: Dict[str, Any]) > None:
        line = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf8")
        self.fh.write(line)
        self.fh.flush()

    def close(self) > None:
        try:
            self.fh.close()
        except Exception:
            pass

def create_client(api_key: str, base_url: str, timeout_s: float) > OpenAI:
    return OpenAI(api_key=api_key, base_url=base_url, timeout=httpx.Timeout(timeout_s))

def make_tools_for_websearch(tool_type: str) > List[Dict[str, Any]]:
    tt = tool_type.strip()
    if not tt:
        tt = "websearch"
    return [{"type": tt}]

def call_responses_structured(
    client: OpenAI,
    model: str,
    prompt: str,
    schema: Dict[str, Any],
    tools: Optional[List[Dict[str, Any]]],
    temperature: float,
    max_output_tokens: int
) > Tuple[str, List[str]]:
    req: Dict[str, Any] = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
                    {
                        "type": "text",
                        "text": "Te egy rendkívül precíz, magyar nyelvű pretraindataset generátor vagy. Kizárólag a megadott JSON sémának megfelelő egyetlen JSON objektumot adj vissza."
                    }
                ]
            },
            {
                "role": "user",
                "content": [{"type": "text", "text": prompt}]
            }
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "strict": True,
                "schema": schema
            }
        },
        "temperature": float(temperature),
        "max_output_tokens": int(max_output_tokens)
    }
    if tools:
        req["tools"] = tools
    resp = client.responses.create(req)
    text, citations = extract_response_text_and_citations(resp)
    return text, citations

def call_chat_structured(
    client: OpenAI,
    model: str,
    prompt: str,
    schema: Dict[str, Any],
    temperature: float,
    max_output_tokens: int
) > str:
    messages = [
        {
            "role": "system",
            "content": "Te egy rendkívül precíz, magyar nyelvű pretraindataset generátor vagy. Kizárólag a megadott JSON sémának megfelelő egyetlen JSON objektumot adj vissza."
        },
        {
            "role": "user",
            "content": prompt
        }
    ]
    kwargs: Dict[str, Any] = {
        "model": model,
        "messages": messages,
        "temperature": float(temperature),
        "max_tokens": int(max_output_tokens)
    }
    try:
        kwargs["response_format"] = {"type": "json_schema", "json_schema": {"name": "hu_pretrain_item", "schema": schema, "strict": True}}
        completion = client.chat.completions.create(kwargs)
        content = completion.choices[0].message.content if completion and completion.choices else ""
        return content or ""
    except Exception:
        try:
            kwargs.pop("response_format", None)
            kwargs["response_format"] = {"type": "json_object"}
            completion = client.chat.completions.create(kwargs)
            content = completion.choices[0].message.content if completion and completion.choices else ""
            return content or ""
        except Exception:
            kwargs.pop("response_format", None)
            completion = client.chat.completions.create(kwargs)
            content = completion.choices[0].message.content if completion and completion.choices else ""
            return content or ""

def generate_one(
    client: OpenAI,
    model: str,
    task: Dict[str, str],
    seed: int,
    schema: Dict[str, Any],
    temperature: float,
    max_output_tokens: int,
    repair_max_output_tokens: int,
    want_search: bool,
    websearch_tool_type: str,
    attempts: int
) > Tuple[Dict[str, Any], str, List[str], str]:
    item_id = sha256_hex(f"{seed}:{task['kind']}:{task['domain']}:{task['difficulty']}")[:16]
    prompt = build_prompt(task, seed, item_id)
    last_text = ""
    last_citations: List[str] = []
    used_mode = ""
    tools = make_tools_for_websearch(websearch_tool_type) if want_search else []
    for attempt in range(1, attempts + 1):
        try:
            text, citations = call_responses_structured(
                client=client,
                model=model,
                prompt=prompt,
                schema=schema,
                tools=tools if want_search else None,
                temperature=temperature,
                max_output_tokens=max_output_tokens
            )
            used_mode = "responses_jsonschema"
            last_text = text
            last_citations = citations
        except Exception:
            text = ""
            citations = []
            try:
                text = call_chat_structured(
                    client=client,
                    model=model,
                    prompt=prompt,
                    schema=schema,
                    temperature=temperature,
                    max_output_tokens=max_output_tokens
                )
                used_mode = "chat_structured"
                last_text = text
                last_citations = citations
            except Exception as e2:
                used_mode = "error"
                last_text = repr(e2)
                last_citations = []
                text = ""
        obj_raw = parse_json_lenient(last_text)
        if obj_raw is not None:
            obj_norm = normalize_obj(obj_raw, task=task, item_id=item_id, citations=last_citations)
            ok = ensure_schema(obj_norm)
            if ok is not None:
                return ok, item_id, last_citations, used_mode
        repair_prompt = build_repair_prompt(task=task, item_id=item_id, bad_text=last_text)
        try:
            repair_text, repair_citations = call_responses_structured(
                client=client,
                model=model,
                prompt=repair_prompt,
                schema=schema,
                tools=None,
                temperature=max(0.0, min(0.2, float(temperature))),
                max_output_tokens=repair_max_output_tokens
            )
            used_mode = used_mode + "+repair_responses"
            last_text = repair_text
            last_citations = repair_citations
        except Exception:
            try:
                repair_text = call_chat_structured(
                    client=client,
                    model=model,
                    prompt=repair_prompt,
                    schema=schema,
                    temperature=max(0.0, min(0.2, float(temperature))),
                    max_output_tokens=repair_max_output_tokens
                )
                used_mode = used_mode + "+repair_chat"
                last_text = repair_text
                last_citations = []
            except Exception:
                pass
        obj_raw2 = parse_json_lenient(last_text)
        if obj_raw2 is not None:
            obj_norm2 = normalize_obj(obj_raw2, task=task, item_id=item_id, citations=last_citations)
            ok2 = ensure_schema(obj_norm2)
            if ok2 is not None:
                return ok2, item_id, last_citations, used_mode
        prompt = build_prompt(task, seed + attempt, item_id)
    raise RuntimeError("Nem sikerült érvényes JSON objektumot generálni a megadott próbálkozásokkal.")

def main() > None:
    api_key = env_str("XAI_API_KEY", "XAIAPIKEY")
    if not api_key:
        raise ValueError("XAI_API_KEY vagy XAIAPIKEY environment variable nincs beállítva")
    base_url = env_str("XAI_BASE_URL", default="") or ""
    model = env_str("XAI_MODEL", default="grok41fastreasoning") or "grok41fastreasoning"
    out_dir = env_str("OUT_DIR", default="datasets_hu_pretrain") or "datasets_hu_pretrain"
    prefix = env_str("FILE_PREFIX", default="hu_pretrain") or "hu_pretrain"
    bytes_per_file = env_int("BYTES_PER_FILE", 1048576)
    sleep_s = env_float("SLEEP_SECONDS", 0.2)
    temperature = env_float("TEMPERATURE", 0.25)
    max_output_tokens = env_int("MAX_OUTPUT_TOKENS", 8192)
    repair_max_output_tokens = env_int("REPAIR_MAX_OUTPUT_TOKENS", 2048)
    timeout_s = env_float("HTTP_TIMEOUT_SECONDS", 3600.0)
    attempts = env_int("ATTEMPTS_PER_ITEM", 3)
    websearch_tool_type = env_str("WEBSEARCH_TOOL_TYPE", default="websearch") or "websearch"
    max_output_tokens = clamp_int(max_output_tokens, 1024, 32768)
    repair_max_output_tokens = clamp_int(repair_max_output_tokens, 512, 8192)
    attempts = clamp_int(attempts, 1, 8)
    seed_base = env_int("SEED", int(time.time()))
    rng = random.Random(seed_base)
    safe_mkdir(out_dir)
    client = create_client(api_key=api_key, base_url=base_url, timeout_s=timeout_s)
    writer = RotatingJsonlWriter(out_dir=out_dir, prefix=prefix, bytes_per_file=bytes_per_file)
    reject_path = os.path.join(out_dir, f"{prefix}_rejected.jsonl")
