def make_tools_for_websearch(tool_type: str) -> List[Dict[str, Any]]:
    tt = (tool_type or "").strip()
    if not tt:
        tt = "web_search"
    aliases = {
        "websearch": "web_search",
        "web_search": "web_search",
        "web-search": "web_search",
        "web_search_preview": "web_search_preview",
    }
    tt = aliases.get(tt, tt)
    return [{"type": tt}]


