    prompt: str,
    schema: Dict[str, Any],
    tools: Optional[List[Dict[str, Any]]],
    temperature: float,
    max_output_tokens: int,
) -> Tuple[str, List[str]]:
    req: Dict[str, Any] = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
