                    }
                ],
            },
            {"role": "user", "content": [{"type": "text", "text": prompt}]},
        ],
        "text": {"format": {"type": "json_schema", "strict": True, "schema": schema}},
        "temperature": float(temperature),
        "max_output_tokens": int(max_output_tokens),
    }
    if tools:
        req["tools"] = tools
    resp = client.responses.create(**req)
    text, citations = extract_response_text_and_citations(resp)
    return text, citations


def call_chat_structured(
    client: OpenAI,
    model: str,
    prompt: str,
    schema: Dict[str, Any],
    temperature: float,
    max_output_tokens: int,
) -> str:
    messages = [
        {
            "role": "system",
            "content": "Te egy rendkívül precíz, magyar nyelvű pretrain-dataset generátor vagy. Kizárólag a megadott JSON sémának megfelelő egyetlen JSON objektumot adj vissza.",
        },
        {"role": "user", "content": prompt},
    ]

    kwargs: Dict[str, Any] = {
        "model": model,
        "messages": messages,
        "temperature": float(temperature),
        "max_tokens": int(max_output_tokens),
    }

    try:
        kwargs["response_format"] = {"type": "json_schema", "json_schema": {"name": "hu_pretrain_item", "schema": schema, "strict": True}}
        completion = client.chat.completions.create(**kwargs)
        content = completion.choices[0].message.content if completion and completion.choices else ""
        return content or ""
    except Exception:
        try:
            kwargs.pop("response_format", None)
            kwargs["response_format"] = {"type": "json_object"}
            completion = client.chat.completions.create(**kwargs)
            content = completion.choices[0].message.content if completion and completion.choices else ""
            return content or ""
        except Exception:
            kwargs.pop("response_format", None)
            completion = client.chat.completions.create(**kwargs)
            content = completion.choices[0].message.content if completion and completion.choices else ""
            return content or ""


def generate_one(
    client: OpenAI,
    model: str,
    task: Dict[str, str],
    seed: int,
    schema: Dict[str, Any],
    temperature: float,
    max_output_tokens: int,
    repair_max_output_tokens: int,
    want_search: bool,
    websearch_tool_type: str,
    attempts: int,
) -> Tuple[Dict[str, Any], str, List[str], str]:
    item_id = sha256_hex(f"{seed}:{task['kind']}:{task['domain']}:{task['difficulty']}")[:16]
    prompt = build_prompt(task, seed, item_id)
    last_text = ""
    last_citations: List[str] = []
    used_mode = ""
    tools = make_tools_for_websearch(websearch_tool_type) if want_search else []

    for attempt in range(1, attempts + 1):
        try:
            text, citations = call_responses_structured(
                client=client,
                model=model,
                prompt=prompt,
                schema=schema,
                tools=tools if want_search else None,
                temperature=temperature,
                max_output_tokens=max_output_tokens,
            )
            used_mode = "responses_jsonschema"
            last_text = text
            last_citations = citations
        except Exception:
            text = ""
            citations = []
            try:
                text = call_chat_structured(
                    client=client,
                    model=model,
                    prompt=prompt,
                    schema=schema,
                    temperature=temperature,
                    max_output_tokens=max_output_tokens,
                )
                used_mode = "chat_structured"
                last_text = text
                last_citations = citations
            except Exception as e2:
                used_mode = "error"
                last_text = repr(e2)
                last_citations = []
                text = ""

        obj_raw = parse_json_lenient(last_text)
        if obj_raw is not None:
            obj_norm = normalize_obj(obj_raw, task=task, item_id=item_id, citations=last_citations)
            ok = ensure_schema(obj_norm)
            if ok is not None:
                return ok, item_id, last_citations, used_mode

        repair_prompt = build_repair_prompt(task=task, item_id=item_id, bad_text=last_text)
        try:
            repair_text, repair_citations = call_responses_structured(
                client=client,
                model=model,
                prompt=repair_prompt,
                schema=schema,
                tools=None,
                temperature=max(0.0, min(0.2, float(temperature))),
                max_output_tokens=repair_max_output_tokens,
            )
            used_mode = used_mode + "+repair_responses"
            last_text = repair_text
            last_citations = repair_citations
        except Exception:
            try:
                repair_text = call_chat_structured(
                    client=client,
                    model=model,
                    prompt=repair_prompt,
                    schema=schema,
                    temperature=max(0.0, min(0.2, float(temperature))),
                    max_output_tokens=repair_max_output_tokens,
                )
                used_mode = used_mode + "+repair_chat"
                last_text = repair_text
                last_citations = []
            except Exception:
                pass

        obj_raw2 = parse_json_lenient(last_text)
        if obj_raw2 is not None:
            obj_norm2 = normalize_obj(obj_raw2, task=task, item_id=item_id, citations=last_citations)
            ok2 = ensure_schema(obj_norm2)
            if ok2 is not None:
                return ok2, item_id, last_citations, used_mode

        prompt = build_prompt(task, seed + attempt, item_id)

    raise RuntimeError("Nem sikerült érvényes JSON objektumot generálni a megadott próbálkozásokkal.")


def main() -> None:
    api_key = env_str("XAI_API_KEY") or env_str("XAIAPIKEY")
    if not api_key:
        raise ValueError("XAI_API_KEY environment variable nincs beállítva")

    base_url = env_str("XAI_BASE_URL", default="https://api.x.ai/v1") or "https://api.x.ai/v1"
    model = env_str("XAI_MODEL", default="grok-4-1-fast-reasoning") or "grok-4-1-fast-reasoning"

    out_dir = env_str("OUT_DIR", default="datasets_hu_pretrain") or "datasets_hu_pretrain"
    prefix = env_str("FILE_PREFIX", default="hu_pretrain") or "hu_pretrain"

    bytes_per_file = env_int("BYTES_PER_FILE", 1048576)
    sleep_s = env_float("SLEEP_SECONDS", 0.2)
    temperature = env_float("TEMPERATURE", 0.25)
    max_output_tokens = env_int("MAX_OUTPUT_TOKENS", 8192)
    repair_max_output_tokens = env_int("REPAIR_MAX_OUTPUT_TOKENS", 2048)
    timeout_s = env_float("HTTP_TIMEOUT_SECONDS", 3600.0)
    attempts = env_int("ATTEMPTS_PER_ITEM", 3)

    websearch_tool_type = env_str("WEBSEARCH_TOOL_TYPE", default="web_search") or "web_search"

    max_output_tokens = clamp_int(max_output_tokens, 1024, 32768)
    repair_max_output_tokens = clamp_int(repair_max_output_tokens, 512, 8192)
    attempts = clamp_int(attempts, 1, 8)

    seed_base = env_int("SEED", int(time.time()))
    rng = random.Random(seed_base)

    safe_mkdir(out_dir)
    client = create_client(api_key=api_key, base_url=base_url, timeout_s=timeout_s)

    writer = RotatingJsonlWriter(out_dir=out_dir, prefix=prefix, bytes_per_file=bytes_per_file)
    reject_path = os.path.join(out_dir, f"{prefix}_rejected.jsonl")
    reject_writer = JsonlAppendWriter(reject_path)

    schema = build_schema()
    catalog = make_task_catalog()

    domains_need_search = {
        "általános_műveltség",
        "magyar_történelem",
        "magyar_földrajz",
        "jog_és_közigazgatás",
        "közgazdaságtan_alapok",
        "természettudomány_alapok",
        "egészség_és_biológia",
    }

    produced = 0
    consecutive_failures = 0
    backoff = 1.0

    print(
        f"START {now_utc_iso()} base_url={base_url} model={model} out_dir={out_dir} bytes_per_file={bytes_per_file} max_output_tokens={max_output_tokens} repair_max_output_tokens={repair_max_output_tokens} attempts={attempts} websearch_tool_type={websearch_tool_type}",
        flush=True,
    )

    try:
        while True:
            seed = rng.randrange(0, 2_000_000_000)
            task = catalog[rng.randrange(0, len(catalog))]
            want_search = task["domain"] in domains_need_search

            print(
                f"REQ {now_utc_iso()} n={produced+1} kind={task['kind']} domain={task['domain']} diff={task['difficulty']} websearch={str(want_search).lower()}",
                flush=True,
            )

            try:
                obj, item_id, citations, mode = generate_one(
                    client=client,
                    model=model,
                    task=task,
                    seed=seed,
                    schema=schema,
                    temperature=temperature,
                    max_output_tokens=max_output_tokens,
                    repair_max_output_tokens=repair_max_output_tokens,
                    want_search=want_search,
                    websearch_tool_type=websearch_tool_type,
                    attempts=attempts,
                )

                content = obj["content"]
                obj_out = {
                    "id": obj["id"],
                    "kind": obj["kind"],
                    "language": "hu",
                    "domain": obj["domain"],
                    "difficulty": obj["difficulty"],
                    "sources": obj.get("sources", []),
                    "content": content,
                    "safety": obj["safety"],
                    "meta": {
                        "generated_at": now_utc_iso(),
                        "model": model,
                        "seed": seed,
                        "item_id": item_id,
                        "generator": mode,
                        "checksum_sha256": sha256_hex(content),
                        "citations_count": len(citations),
                    },
                }

                path, idx, b = writer.write_obj(obj_out)
                produced += 1
                consecutive_failures = 0
                backoff = 1.0

                print(
                    f"OK {now_utc_iso()} n={produced} file={os.path.basename(path)} file_index={idx} file_bytes={b}",
                    flush=True,
                )

                if sleep_s > 0:
                    time.sleep(sleep_s)

            except KeyboardInterrupt:
                print(f"STOP {now_utc_iso()} produced={produced}", flush=True)
                break

            except Exception as e:
                consecutive_failures += 1
                et = repr(e)
                reject_writer.write({"at": now_utc_iso(), "seed": seed, "task": task, "error": et})
                print(
                    f"ERR {now_utc_iso()} failures={consecutive_failures} backoff={backoff:.2f}s error={et}",
                    file=sys.stderr,
                    flush=True,
                )
                if consecutive_failures >= 2:
                    backoff = min(max(1.0, backoff) * 1.8, 60.0)
                    time.sleep(backoff)

    finally:
        try:
            reject_writer.close()
        except Exception:
            pass
        try:
            writer.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

Nem lehet garantálni, hogy bármilyen „szupertiszta” dataset önmagában a világ legjobb LLMjét adja, vagy hogy egy modell „a teljes földi tudást” elsajátítja.  
Viszont adható egy sokkal szigorúbb, hibákra és zajra kevésbé érzékeny, pretrainkorpusz generátor, ami erős minőségszűrést, deduplikációt, PIIszűrést és stabilabb APIhívásokat használ.

 Reális elvárások
A „JAIDE v40” leírásod erősen ambiciózus rendszert vázol (SSRG/KRGU/RSF/ESSO, formális verifikáció, stb.), de ettől függetlenül a tanítóadat minősége és jogtisztasága marad a legkritikusabb szűk keresztmetszet.[1]
A nagy modellek adatpipelineja tipikusan: agresszív tisztítás + deduplikáció + minőségi szűrők + licenc/PII kontroll, mert ezek közvetlenül befolyásolják a tanulás hasznosságát.

 Javított generátor
Az alábbi egyfájlos kód a korábbi sémádon alapul (id/kind/language/domain/difficulty/sources/content/safety/meta), és hozzáad: szövegnormalizálás, PIIheurisztikák, zaj/fillerszűrés, hosszkorlátok, LRUszerű deduplikáció cache, opcionális modellspec beolvasás, SIGINT/SIGTERM leállás.[1]
„100% hibamentességet” nem lehet őszintén garantálni minden környezetben (függ az SDK verziótól, xAI/OpenAI kompatibilitástól, hálózattól), de a fájl szintaktikailag konzisztens, és production jellegű védőkorlátokat tartalmaz.

