def now_utc_iso() -> str:
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"


def sha256_hex(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


def safe_mkdir(path: str) -> None:
    os.makedirs(path, exist_ok=True)


def clamp_int(x: int, lo: int, hi: int) -> int:
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def looks_hungarian(text: str) -> bool:
    if not text or len(text) < 200:
        return False
    hu_chars = "áéíóöőúüűÁÉÍÓÖŐÚÜŰ"
    hu_count = sum(1 for ch in text if ch in hu_chars)
    alpha_count = sum(1 for ch in text if ch.isalpha())
    if alpha_count == 0:
        return False
    if hu_count >= 6:
        return True
    ratio = hu_count / max(1, alpha_count)
    if ratio >= 0.003:
        return True
    common = [
        "hogy",
        "és",
        "nem",
        "van",
        "mert",
        "szerint",
        "külön",
        "ugyan",
        "továbbá",
        "valamint",
        "azonban",
        "ezért",
        "illetve",
    ]
    tl = text.lower()
    hits = sum(1 for w in common if w in tl)
    return hits >= 3


def normalize_text(s: str) -> str:
    if not isinstance(s, str):
        return ""
    s = s.replace("\r\n", "\n").replace("\r", "\n")
    s = re.sub(r"[ \t]+", " ", s)
    s = re.sub(r"\n{4,}", "\n\n\n", s)
    return s.strip()


def contains_pii(text: str) -> bool:
    if not text:
        return False
    email_re = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
    phone_re = re.compile(r"(?:(?:\+|00)\d{1,3}[ \-]?)?(?:\(\d{1,4}\)[ \-]?)?\d{2,4}[ \-]?\d{2,4}[ \-]?\d{2,4}")
    cc_re = re.compile(r"\b(?:\d[ -]*?){13,19}\b")
    if email_re.search(text):
        return True
    if phone_re.search(text):
        return True
    for m in cc_re.finditer(text):
        digits = re.sub(r"\D", "", m.group(0))
        if 13 <= len(digits) <= 19:
            return True
    return False


def passes_quality_heuristics(text: str, min_chars: int, max_chars: int) -> bool:
    if not isinstance(text, str):
        return False
    t = text.strip()
    if len(t) < min_chars:
        return False
    if max_chars > 0 and len(t) > max_chars:
        return False
    if contains_pii(t):
        return False
    if not looks_hungarian(t):
        return False
    if re.search(r"\b(várj|vrj|oké\s+na|ööö|hmm)\b", t.lower()):
        return False
    if t.count("...") >= 2:
        return False
    alpha = sum(1 for ch in t if ch.isalpha())
    if alpha == 0:
        return False
    uniq_ratio = len(set(t)) / max(1, len(t))
    if uniq_ratio < 0.015:
        return False
    if re.search(r"(.)\1{12,}", t):
        return False
    return True


def parse_json_lenient(s: str) -> Optional[Dict[str, Any]]:
    if not isinstance(s, str) or not s.strip():
        return None
    s2 = s.strip()
    try:
        out = json.loads(s2)
        return out if isinstance(out, dict) else None
    except Exception:
        pass
    start = s2.find("{")
    end = s2.rfind("}")
    if start != -1 and end != -1 and end > start:
        try:
            out = json.loads(s2[start:end + 1])
            return out if isinstance(out, dict) else None
        except Exception:
            return None
    return None


def extract_response_text_and_citations(resp: Any) -> Tuple[str, List[str]]:
    d: Dict[str, Any] = {}
    if hasattr(resp, "model_dump"):
        try:
            d = resp.model_dump()
        except Exception:
            d = {}
    elif isinstance(resp, dict):
        d = resp
    else:
        try:
            d = json.loads(str(resp))
        except Exception:
            d = {}

    citations_urls: List[str] = []
    c = d.get("citations")
    if isinstance(c, list):
        for item in c:
            if isinstance(item, dict):
                u = item.get("url") or item.get("source") or item.get("link")
                if isinstance(u, str) and u.startswith("http"):
                    citations_urls.append(u)
            elif isinstance(item, str) and item.startswith("http"):
                citations_urls.append(item)

    if isinstance(d.get("output_text"), str):
        return d["output_text"], list(dict.fromkeys(citations_urls))

    output = d.get("output")
    if isinstance(output, list):
        parts: List[str] = []
        for item in output:
            if not isinstance(item, dict):
                continue
            itype = item.get("type")
            if itype in ("output_text", "text"):
                t = item.get("text")
                if isinstance(t, str):
                    parts.append(t)
                    continue
            content = item.get("content")
            if isinstance(content, list):
                for c2 in content:
                    if isinstance(c2, dict) and c2.get("type") in ("output_text", "text"):
                        t2 = c2.get("text")
                        if isinstance(t2, str):
                            parts.append(t2)
        if parts:
            return "".join(parts), list(dict.fromkeys(citations_urls))

    return "", list(dict.fromkeys(citations_urls))


def build_schema() -> Dict[str, Any]:
    return {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "id": {"type": "string"},
            "kind": {"type": "string", "enum": ["article", "dialogue", "qa", "instructions", "code", "math", "reasoning"]},
            "language": {"type": "string", "enum": ["hu"]},
            "domain": {"type": "string"},
            "difficulty": {"type": "string", "enum": ["alacsony", "átlagos", "közepes", "haladó", "doktori"]},
            "sources": {"type": "array", "items": {"type": "string"}, "minItems": 0},
            "content": {"type": "string"},
            "safety": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "pii": {"type": "boolean", "enum": [False]},
                    "copyright_safe": {"type": "boolean", "enum": [True]},
                    "hallucination_risk": {"type": "string", "enum": ["low", "medium"]},
                    "notes": {"type": "string"},
                },
                "required": ["pii", "copyright_safe", "hallucination_risk", "notes"],
            },
        },
        "required": ["id", "kind", "language", "domain", "difficulty", "content", "safety"],
    }


def ensure_schema(obj: Dict[str, Any], min_chars: int, max_chars: int) -> Optional[Dict[str, Any]]:
    if not isinstance(obj, dict):
        return None
    required_top = ["id", "kind", "language", "domain", "difficulty", "content", "safety"]
    for k in required_top:
        if k not in obj:
            return None
    if obj.get("language") != "hu":
        return None
    if not isinstance(obj.get("id"), str) or len(obj["id"]) < 8:
        return None
    if obj.get("kind") not in ["article", "dialogue", "qa", "instructions", "code", "math", "reasoning"]:
        return None
    if not isinstance(obj.get("domain"), str) or len(obj["domain"].strip()) < 2:
        return None
    if obj.get("difficulty") not in ["alacsony", "átlagos", "közepes", "haladó", "doktori"]:
        return None

    safety = obj.get("safety")
    if not isinstance(safety, dict):
        return None
    if safety.get("pii") is not False:
        return None
    if safety.get("copyright_safe") is not True:
        return None
    if safety.get("hallucination_risk") not in ["low", "medium"]:
        return None
    notes = safety.get("notes")
    if not isinstance(notes, str) or not notes.strip():
        return None

    content = obj.get("content")
    if not isinstance(content, str):
        return None
    content = normalize_text(content)
    if not passes_quality_heuristics(content, min_chars=min_chars, max_chars=max_chars):
        return None

    sources = obj.get("sources")
    if sources is not None and not isinstance(sources, list):
        return None

    obj["content"] = content
    return obj


