def read_optional_text_file(path: Optional[str], max_chars: int) -> str:
    if not path:
        return ""
    try:
        with open(path, "rb") as f:
            data = f.read(max_chars + 1)
        txt = data.decode("utf-8", errors="replace")
        txt = normalize_text(txt)
        if len(txt) > max_chars:
            txt = txt[:max_chars]
        return txt
    except Exception:
        return ""


def build_prompt(task: Dict[str, str], seed: int, item_id: str, min_chars: int, max_chars: int, model_spec: str) -> str:
