        f"Az 'id' mező értéke pontosan ez legyen: {item_id}\n"
        f"A 'kind' mező értéke pontosan ez legyen: {kind}\n"
        f"A 'domain' mező értéke pontosan ez legyen: {domain}\n"
        f"A 'difficulty' mező értéke pontosan ez legyen: {difficulty}\n"
        "A 'language' mező értéke pontosan: hu\n"
        "A 'safety' mezőben: pii=false, copyright_safe=true, hallucination_risk=low vagy medium, notes pedig rövid, lényegi mondat.\n"
        "A 'sources' mezőbe csak valós, ellenőrizhető URL-ek kerüljenek, kizárólag akkor, ha tényszerű részhez ténylegesen használtad a webeszközt.\n"
        f"A 'content' legalább {min_chars} karakter{max_part}, magyar, nyelvhelyes, természetes, változatos.\n"
        f"Seed: {seed}\n"
        + spec_part +
        "Most add vissza a JSON-t a séma szerint.\n"
    )


def build_repair_prompt(task: Dict[str, str], item_id: str, bad_text: str, min_chars: int, max_chars: int) -> str:
    kind = task["kind"]
    domain = task["domain"]
    difficulty = task["difficulty"]
    max_part = ""
    if max_chars > 0:
        max_part = f", max_chars={max_chars}"
    return (
        "Javítsd az alábbi kimenetet úgy, hogy kizárólag egyetlen, érvényes JSON objektum legyen, és pontosan megfeleljen a megadott sémának.\n"
        "Semmilyen magyarázatot ne adj, csak a JSON-t.\n"
        f"Elvárt mezők: id={item_id}, kind={kind}, language=hu, domain={domain}, difficulty={difficulty}, sources(list), content(string min_chars={min_chars}{max_part}), safety(obj: pii=false, copyright_safe=true, hallucination_risk=low/medium, notes=string).\n"
        "Kizárólag eredeti, saját szöveget írj; ne idézz külső forrásból.\n"
        "Ne írj személyes adatot.\n"
        "Kerüld a töredezett, javítgatós szöveget, a túl sok pontozást, és a filler szavakat.\n"
        "Hibás bemenet:\n" + bad_text
    )


def normalize_obj(obj: Dict[str, Any], task: Dict[str, str], item_id: str, citations: Optional[List[str]] = None) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    out["id"] = obj.get("id") if isinstance(obj.get("id"), str) and len(obj.get("id", "")) >= 8 else item_id
    out["kind"] = task["kind"]
    out["language"] = "hu"
    out["domain"] = task["domain"]
    out["difficulty"] = task["difficulty"]

    sources: List[str] = []
    raw_sources = obj.get("sources")
    if isinstance(raw_sources, list):
        for u in raw_sources:
            if isinstance(u, str) and u.startswith("http"):
                sources.append(u)
    if citations:
        for u in citations:
            if isinstance(u, str) and u.startswith("http"):
                sources.append(u)
    out["sources"] = list(dict.fromkeys(sources))

    content = obj.get("content")
    out["content"] = normalize_text(content) if isinstance(content, str) else ""

    safety_in = obj.get("safety")
    if isinstance(safety_in, dict):
        hr = safety_in.get("hallucination_risk")
        notes = safety_in.get("notes")
        out["safety"] = {
            "pii": False,
            "copyright_safe": True,
            "hallucination_risk": hr if hr in ("low", "medium") else "medium",
            "notes": notes.strip() if isinstance(notes, str) and notes.strip() else "Automatikusan normalizált biztonsági mezők.",
        }
    else:
        out["safety"] = {
            "pii": False,
            "copyright_safe": True,
            "hallucination_risk": "medium",
            "notes": "Hiányzó safety mezők automatikusan pótolva.",
        }

    return out


class RotatingJsonlWriter:
    def __init__(self, out_dir: str, prefix: str, bytes_per_file: int) -> None:
        self.out_dir = out_dir
        self.prefix = prefix
        self.bytes_per_file = bytes_per_file
        self.state_path = os.path.join(out_dir, f"{prefix}.state.json")
        self.file_index = 1
        self.bytes_written_current = 0
        self.fh: Optional[Any] = None
        safe_mkdir(out_dir)
        self._load_state()
        self._open_current()

    def _load_state(self) -> None:
        try:
            with open(self.state_path, "rb") as f:
                st = json.loads(f.read().decode("utf-8"))
            if isinstance(st, dict):
                self.file_index = int(st.get("file_index", 1))
        except Exception:
            self.file_index = 1

    def _save_state(self) -> None:
        st = {"file_index": self.file_index, "updated_at": now_utc_iso()}
        tmp = self.state_path + ".tmp"
        with open(tmp, "wb") as f:
            f.write(json.dumps(st, ensure_ascii=False).encode("utf-8"))
        os.replace(tmp, self.state_path)

    def _file_path(self, idx: int) -> str:
        return os.path.join(self.out_dir, f"{self.prefix}_{idx:06d}.jsonl")

    def _open_current(self) -> None:
        if self.fh is not None:
            try:
                self.fh.close()
            except Exception:
                pass
        path = self._file_path(self.file_index)
        self.fh = open(path, "ab")
        try:
            self.fh.seek(0, 2)
            self.bytes_written_current = int(self.fh.tell())
        except Exception:
            self.bytes_written_current = 0

    def _rotate(self) -> None:
        if self.fh is not None:
            try:
                self.fh.flush()
            except Exception:
                pass
        self.file_index += 1
        self._save_state()
        self._open_current()

    def write_obj(self, obj: Dict[str, Any]) -> Tuple[str, int, int]:
        line = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf-8")
        if self.bytes_written_current + len(line) > self.bytes_per_file:
            self._rotate()
        if self.fh is None:
            raise RuntimeError("Writer nincs megnyitva")
        self.fh.write(line)
        self.fh.flush()
        self.bytes_written_current += len(line)
        return self._file_path(self.file_index), self.file_index, self.bytes_written_current

    def close(self) -> None:
        if self.fh is not None:
            try:
                self.fh.flush()
            except Exception:
                pass
            try:
                self.fh.close()
            except Exception:
                pass
            self.fh = None


class JsonlAppendWriter:
    def __init__(self, path: str) -> None:
        self.path = path
        safe_mkdir(os.path.dirname(path) or ".")
        self.fh = open(path, "ab")

    def write(self, obj: Dict[str, Any]) -> None:
        line = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf-8")
        self.fh.write(line)
        self.fh.flush()

    def close(self) -> None:
        try:
            self.fh.close()
        except Exception:
            pass


def create_client(api_key: str, base_url: str, timeout_s: float) -> OpenAI:
    return OpenAI(api_key=api_key, base_url=base_url, timeout=httpx.Timeout(timeout_s))


def make_tools_for_websearch(tool_type: str) -> List[Dict[str, Any]]:
    tt = (tool_type or "").strip()
    if not tt:
        tt = "web_search"
    aliases = {
        "websearch": "web_search",
        "web_search": "web_search",
        "web-search": "web_search",
        "web_search_preview": "web_search_preview",
        "websearch_preview": "web_search_preview",
    }
    tt = aliases.get(tt, tt)
    return [{"type": tt}]


def call_responses_structured(
    client: OpenAI,
    model: str,
    prompt: str,
    schema: Dict[str, Any],
    tools: Optional[List[Dict[str, Any]]],
    temperature: float,
    max_output_tokens: int,
    max_retries: int,
    base_backoff_s: float,
) -> Tuple[str, List[str], str]:
    req: Dict[str, Any] = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
                    {
                        "type": "text",
                        "text": "Te egy rendkívül precíz, magyar nyelvű pretrain-dataset generátor vagy. Kizárólag a megadott JSON sémának megfelelő egyetlen JSON objektumot adj vissza.",
                    }
                ],
            },
            {"role": "user", "content": [{"type": "text", "text": prompt}]},
        ],
        "text": {"format": {"type": "json_schema", "strict": True, "schema": schema}},
        "temperature": float(temperature),
        "max_output_tokens": int(max_output_tokens),
    }
    if tools:
        req["tools"] = tools

    last_err = ""
    tries = max(1, int(max_retries) + 1)
    for i in range(tries):
        try:
            resp = client.responses.create(**req)
            text, citations = extract_response_text_and_citations(resp)
            return text, citations, "responses_jsonschema"
        except Exception as e:
            last_err = repr(e)
            if i >= tries - 1:
                break
            sleep_s = float(base_backoff_s) * (2 ** i) + random.random() * 0.25
            time.sleep(min(30.0, sleep_s))
    raise RuntimeError(last_err)


def call_chat_structured(
    client: OpenAI,
    model: str,
    prompt: str,
    schema: Dict[str, Any],
    temperature: float,
    max_output_tokens: int,
) -> str:
    messages = [
        {
            "role": "system",
            "content": "Te egy rendkívül precíz, magyar nyelvű pretrain-dataset generátor vagy. Kizárólag a megadott JSON sémának megfelelő egyetlen JSON objektumot adj vissza.",
        },
        {"role": "user", "content": prompt},
    ]

    kwargs: Dict[str, Any] = {
        "model": model,
        "messages": messages,
        "temperature": float(temperature),
        "max_tokens": int(max_output_tokens),
    }

    try:
        kwargs["response_format"] = {"type": "json_schema", "json_schema": {"name": "hu_pretrain_item", "schema": schema, "strict": True}}
        completion = client.chat.completions.create(**kwargs)
        content = completion.choices[0].message.content if completion and completion.choices else ""
        return content or ""
    except Exception:
        try:
            kwargs.pop("response_format", None)
            kwargs["response_format"] = {"type": "json_object"}
            completion = client.chat.completions.create(**kwargs)
            content = completion.choices[0].message.content if completion and completion.choices else ""
            return content or ""
        except Exception:
            kwargs.pop("response_format", None)
            completion = client.chat.completions.create(**kwargs)
            content = completion.choices[0].message.content if completion and completion.choices else ""
            return content or ""


def generate_one(
    client: OpenAI,
    model: str,
    task: Dict[str, str],
    seed: int,
    schema: Dict[str, Any],
    temperature: float,
    max_output_tokens: int,
    repair_max_output_tokens: int,
    want_search: bool,
    websearch_tool_type: str,
    attempts: int,
    min_chars: int,
    max_chars: int,
    model_spec: str,
    api_retries: int,
    api_backoff_s: float,
) -> Tuple[Dict[str, Any], str, List[str], str]:
    item_id = sha256_hex(f"{seed}:{task['kind']}:{task['domain']}:{task['difficulty']}")[:16]
    prompt = build_prompt(task, seed, item_id, min_chars=min_chars, max_chars=max_chars, model_spec=model_spec)

    last_text = ""
    last_citations: List[str] = []
    used_mode = ""
    tools = make_tools_for_websearch(websearch_tool_type) if want_search else []

    for attempt in range(1, int(attempts) + 1):
        try:
            text, citations, mode = call_responses_structured(
                client=client,
                model=model,
                prompt=prompt,
                schema=schema,
                tools=tools if want_search else None,
                temperature=temperature,
                max_output_tokens=max_output_tokens,
                max_retries=api_retries,
                base_backoff_s=api_backoff_s,
            )
            used_mode = mode
            last_text = text
            last_citations = citations
        except Exception:
            try:
                text = call_chat_structured(
                    client=client,
                    model=model,
                    prompt=prompt,
                    schema=schema,
                    temperature=temperature,
                    max_output_tokens=max_output_tokens,
                )
                used_mode = "chat_structured"
                last_text = text
                last_citations = []
            except Exception as e2:
                used_mode = "error"
                last_text = repr(e2)
                last_citations = []

        obj_raw = parse_json_lenient(last_text)
        if obj_raw is not None:
            obj_norm = normalize_obj(obj_raw, task=task, item_id=item_id, citations=last_citations)
            ok = ensure_schema(obj_norm, min_chars=min_chars, max_chars=max_chars)
            if ok is not None:
                return ok, item_id, last_citations, used_mode

        repair_prompt = build_repair_prompt(task=task, item_id=item_id, bad_text=last_text, min_chars=min_chars, max_chars=max_chars)
        try:
            repair_text, repair_citations, mode2 = call_responses_structured(
                client=client,
                model=model,
                prompt=repair_prompt,
                schema=schema,
                tools=None,
                temperature=max(0.0, min(0.2, float(temperature))),
                max_output_tokens=repair_max_output_tokens,
                max_retries=api_retries,
                base_backoff_s=api_backoff_s,
            )
            used_mode = used_mode + "+repair_" + mode2
            last_text = repair_text
            last_citations = repair_citations
        except Exception:
            try:
                repair_text = call_chat_structured(
                    client=client,
                    model=model,
                    prompt=repair_prompt,
                    schema=schema,
                    temperature=max(0.0, min(0.2, float(temperature))),
                    max_output_tokens=repair_max_output_tokens,
                )
                used_mode = used_mode + "+repair_chat"
                last_text = repair_text
                last_citations = []
            except Exception:
                pass

        obj_raw2 = parse_json_lenient(last_text)
        if obj_raw2 is not None:
            obj_norm2 = normalize_obj(obj_raw2, task=task, item_id=item_id, citations=last_citations)
            ok2 = ensure_schema(obj_norm2, min_chars=min_chars, max_chars=max_chars)
            if ok2 is not None:
                return ok2, item_id, last_citations, used_mode

        prompt = build_prompt(task, seed + attempt, item_id, min_chars=min_chars, max_chars=max_chars, model_spec=model_spec)

    raise RuntimeError("Nem sikerült érvényes JSON objektumot generálni a megadott próbálkozásokkal.")


class DedupCache:
    def __init__(self, max_items: int) -> None:
        self.max_items = max(0, int(max_items))
        self.map: Dict[str, float] = {}

    def seen_or_add(self, key: str) -> bool:
        if self.max_items <= 0:
            return False
        now = time.time()
        if key in self.map:
            self.map[key] = now
            return True
        self.map[key] = now
        if len(self.map) > self.max_items:
            items = sorted(self.map.items(), key=lambda kv: kv[1])
            drop = max(1, len(self.map) - self.max_items)
            for k, _ in items[:drop]:
                self.map.pop(k, None)
        return False


def main() -> None:
    api_key = env_str("XAI_API_KEY") or env_str("XAIAPIKEY")
    if not api_key:
        raise ValueError("XAI_API_KEY environment variable nincs beállítva")

    base_url = env_str("XAI_BASE_URL", default="https://api.x.ai/v1") or "https://api.x.ai/v1"
    model = env_str("XAI_MODEL", default="grok-4-1-fast-reasoning") or "grok-4-1-fast-reasoning"

    out_dir = env_str("OUT_DIR", default="datasets_hu_pretrain") or "datasets_hu_pretrain"
    prefix = env_str("FILE_PREFIX", default="hu_pretrain") or "hu_pretrain"

    bytes_per_file = env_int("BYTES_PER_FILE", 1048576)
    sleep_s = env_float("SLEEP_SECONDS", 0.2)
    temperature = env_float("TEMPERATURE", 0.25)
    max_output_tokens = env_int("MAX_OUTPUT_TOKENS", 8192)
    repair_max_output_tokens = env_int("REPAIR_MAX_OUTPUT_TOKENS", 2048)
    timeout_s = env_float("HTTP_TIMEOUT_SECONDS", 3600.0)
    attempts = env_int("ATTEMPTS_PER_ITEM", 3)
    websearch_tool_type = env_str("WEBSEARCH_TOOL_TYPE", default="web_search") or "web_search"

    min_chars = env_int("MIN_CONTENT_CHARS", 900)
    max_chars = env_int("MAX_CONTENT_CHARS", 0)

    api_retries = clamp_int(env_int("API_RETRIES", 2), 0, 8)
    api_backoff_s = max(0.05, env_float("API_BACKOFF_SECONDS", 0.6))

    dedup_max = env_int("DEDUP_MAX", 200000)

    max_output_tokens = clamp_int(max_output_tokens, 1024, 32768)
    repair_max_output_tokens = clamp_int(repair_max_output_tokens, 512, 8192)
    attempts = clamp_int(attempts, 1, 8)
    min_chars = clamp_int(min_chars, 400, 12000)
    if max_chars > 0:
        max_chars = max(max_chars, min_chars)

    seed_base = env_int("SEED", int(time.time()))
    rng = random.Random(seed_base)

    model_spec_path = env_str("MODEL_SPEC_PATH")
    model_spec = read_optional_text_file(model_spec_path, max_chars=12000)

    safe_mkdir(out_dir)
    client = create_client(api_key=api_key, base_url=base_url, timeout_s=timeout_s)

    writer = RotatingJsonlWriter(out_dir=out_dir, prefix=prefix, bytes_per_file=bytes_per_file)
    reject_path = os.path.join(out_dir, f"{prefix}_rejected.jsonl")
    reject_writer = JsonlAppendWriter(reject_path)

    schema = build_schema()
    catalog = make_task_catalog()

    domains_need_search = {
        "általános_műveltség",
        "magyar_történelem",
        "magyar_földrajz",
        "jog_és_közigazgatás",
        "közgazdaságtan_alapok",
        "természettudomány_alapok",
        "egészség_és_biológia",
    }

    dedup = DedupCache(max_items=dedup_max)
    stop_flag = {"stop": False}

    def _handle_sig(_signum: int, _frame: Any) -> None:
        stop_flag["stop"] = True

    try:
        signal.signal(signal.SIGINT, _handle_sig)
    except Exception:
        pass
    try:
        signal.signal(signal.SIGTERM, _handle_sig)
    except Exception:
        pass

    produced = 0
    consecutive_failures = 0
    backoff = 1.0

    print(
        f"START {now_utc_iso()} base_url={base_url} model={model} out_dir={out_dir} bytes_per_file={bytes_per_file} max_output_tokens={max_output_tokens} repair_max_output_tokens={repair_max_output_tokens} attempts={attempts} websearch_tool_type={websearch_tool_type} min_chars={min_chars} max_chars={max_chars}",
        flush=True,
    )

    try:
        while not stop_flag["stop"]:
            seed = rng.randrange(0, 2_000_000_000)
            task = catalog[rng.randrange(0, len(catalog))]
            want_search = task["domain"] in domains_need_search

            print(
                f"REQ {now_utc_iso()} n={produced+1} kind={task['kind']} domain={task['domain']} diff={task['difficulty']} websearch={str(want_search).lower()}",
                flush=True,
            )

            try:
                obj, item_id, citations, mode = generate_one(
                    client=client,
                    model=model,
                    task=task,
                    seed=seed,
                    schema=schema,
                    temperature=temperature,
                    max_output_tokens=max_output_tokens,
                    repair_max_output_tokens=repair_max_output_tokens,
                    want_search=want_search,
                    websearch_tool_type=websearch_tool_type,
                    attempts=attempts,
                    min_chars=min_chars,
                    max_chars=max_chars,
                    model_spec=model_spec,
                    api_retries=api_retries,
                    api_backoff_s=api_backoff_s,
                )

                content = obj["content"]
                content_hash = sha256_hex(content)
                if dedup.seen_or_add(content_hash):
                    reject_writer.write({"at": now_utc_iso(), "seed": seed, "task": task, "error": "duplicate_content"})
                    if sleep_s > 0:
                        time.sleep(sleep_s)
                    continue

                obj_out = {
                    "id": obj["id"],
                    "kind": obj["kind"],
                    "language": "hu",
                    "domain": obj["domain"],
                    "difficulty": obj["difficulty"],
                    "sources": obj.get("sources", []),
                    "content": content,
                    "safety": obj["safety"],
                    "meta": {
                        "generated_at": now_utc_iso(),
                        "model": model,
                        "seed": seed,
                        "item_id": item_id,
                        "generator": mode,
                        "checksum_sha256": content_hash,
                        "citations_count": len(citations),
                    },
                }

                path, idx, b = writer.write_obj(obj_out)
                produced += 1
                consecutive_failures = 0
                backoff = 1.0

                print(
                    f"OK {now_utc_iso()} n={produced} file={os.path.basename(path)} file_index={idx} file_bytes={b}",
                    flush=True,
                )

                if sleep_s > 0:
                    time.sleep(sleep_s)

            except Exception as e:
                consecutive_failures += 1
                et = repr(e)
                reject_writer.write({"at": now_utc_iso(), "seed": seed, "task": task, "error": et})
                print(
                    f"ERR {now_utc_iso()} failures={consecutive_failures} backoff={backoff:.2f}s error={et}",
                    file=sys.stderr,
                    flush=True,
                )
                if consecutive_failures >= 2:
                    backoff = min(max(1.0, backoff) * 1.8, 60.0)
                    time.sleep(backoff)

    finally:
        try:
            reject_writer.close()
        except Exception:
            pass
        try:
            writer.close()
        except Exception:
            pass

    print(f"STOP {now_utc_iso()} produced={produced}", flush=True)


if __name__ == "__main__":
    main()
